def starting_steps(n: int, triggers: list[list[int]]) -> list[int]:
    fired = [False] * n                  # fired[s]: some trigger points at s (in-degree > 0)
    for _, b in triggers:
        fired[b] = True
    return [s for s in range(n) if not fired[s]]

