from collections import deque


def starting_steps(n: int, triggers: list[list[int]]) -> list[int]:
    fires = [[] for _ in range(n)]
    for a, b in triggers:
        fires[a].append(b)
    reached = [False] * n                # set off by some other step
    for start in range(n):               # launch each step and see what it sets off
        seen = [False] * n
        queue = deque([start])
        while queue:
            u = queue.popleft()
            for v in fires[u]:
                if not seen[v]:
                    seen[v] = reached[v] = True
                    queue.append(v)
    return [s for s in range(n) if not reached[s]]
